class TestAssistantMutationView(BloomerpAPIViewTestCase):
    """Tests class `AssistantMutationView` from `bloomerp/views/api/mutations.py`."""

    view_name = "api_assistant_mutations"

    def extendedSetup(self) -> None:
        """Use the same model identity supplied by shared object artifacts."""
        self.model_label = Initiative._meta.label

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover canonical mutations, access checks, and API discovery."""
        return [
            RequestScenario(
                name="Assistant mutation creates an object",
                description=(
                    "UC: An administrator asks the assistant to create a generated API resource.\n"
                    "Expected Result: The object is created and returned with the create operation."
                ),
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                data={
                    "model_label": self.model_label,
                    "operation": "create",
                    "data": {"name": "Backend", "description": "Backend initiative"},
                },
                expected=ExpectedResult(
                    status_code=201,
                    response_validators=self.object_was_created,
                ),
            ),
            RequestScenario(
                name="Assistant mutation updates an object",
                description=(
                    "UC: An administrator updates an existing generated API resource.\n"
                    "Expected Result: The requested field is persisted and returned."
                ),
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                prepare=self.prepare_update,
                expected=ExpectedResult(response_validators=self.object_was_updated),
            ),
            RequestScenario(
                name="Assistant mutation deletes an object",
                description=(
                    "UC: An administrator deletes an existing generated API resource.\n"
                    "Expected Result: The response identifies it and the row no longer exists."
                ),
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                prepare=self.prepare_delete,
                expected=ExpectedResult(response_validators=self.object_was_deleted),
            ),
            RequestScenario(
                name="Assistant mutation rejects unknown model label",
                description=(
                    "UC: The assistant supplies a model label that has no generated API.\n"
                    "Expected Result: The endpoint returns a model-label validation error."
                ),
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                data={
                    "model_label": "bloomerp.UnknownModel",
                    "operation": "create",
                    "data": {},
                },
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=self.json_exact(
                        {"model_label": "Unknown generated API model."}
                    ),
                ),
            ),
            RequestScenario(
                name="Assistant mutation preserves generated API write permissions",
                description=(
                    "UC: A user without generated-model write access requests a mutation.\n"
                    "Expected Result: The request is forbidden and no object is created."
                ),
                method="POST",
                user=self.normal_user,
                content_type="application/json",
                data={
                    "model_label": self.model_label,
                    "operation": "create",
                    "data": {
                        "name": "Unauthorized",
                        "description": "Backend initiative",
                    },
                },
                expected=ExpectedResult(
                    status_code=403,
                    response_validators=self.unauthorized_object_absent,
                ),
            ),
            RequestScenario(
                name="OpenAPI schema documents assistant mutation routes",
                description=(
                    "UC: A client discovers assistant mutation APIs from OpenAPI.\n"
                    "Expected Result: Both mutation paths and catalog query parameters are documented."
                ),
                view_name="schema",
                query_params={"format": "json"},
                expected=ExpectedResult(
                    response_validators=self.schema_documents_mutations
                ),
            ),
        ]

    def unauthorized_object_absent(self, response: HttpResponse) -> bool:
        """Verify denied write requests leave no unauthorized initiative in storage."""
        return not Initiative.objects.filter(name="Unauthorized").exists()

    def create_initiative(self, **overrides: Any) -> Initiative:
        """Create a reusable initiative fixture with supplied field overrides."""
        values = {"name": "Backend", "description": "Backend initiative"}
        values.update(overrides)
        return Initiative.objects.create(**values)

    def prepare_update(self, scenario: RequestScenario) -> None:
        """Prepare a direct update using a shared model-label identity."""
        self.initiative = self.create_initiative(name="Before")
        scenario.data = {
            "model_label": self.model_label,
            "operation": "update",
            "object_id": str(self.initiative.pk),
            "data": {"name": "Updated"},
        }

    def prepare_delete(self, scenario: RequestScenario) -> None:
        """Prepare a direct deletion using a shared model-label identity."""
        self.initiative = self.create_initiative()
        scenario.data = {
            "model_label": self.model_label,
            "operation": "delete",
            "object_id": str(self.initiative.pk),
        }

    def object_was_created(self, response: HttpResponse) -> bool:
        """Verify the returned created object exists in persistent storage."""
        payload = response.json()
        return (
            payload.get("operation") == "create"
            and Initiative.objects.filter(pk=payload["object"]["id"]).exists()
        )

    def object_was_updated(self, response: HttpResponse) -> bool:
        """Verify the response and persistent initiative contain the requested update."""
        self.initiative.refresh_from_db()
        return (
            response.json()["object"]["name"] == "Updated"
            and self.initiative.name == "Updated"
        )

    def object_was_deleted(self, response: HttpResponse) -> bool:
        """Verify the requested initiative was deleted and its identity is returned."""
        return (
            response.json().get("object_id") == str(self.initiative.pk)
            and not Initiative.objects.filter(pk=self.initiative.pk).exists()
        )

    @staticmethod
    def schema_documents_mutations(response: HttpResponse) -> bool:
        """Verify discovery exposes the canonical model-label catalog filter."""
        paths = response.json()["paths"]
        parameter_names = {
            parameter["name"]
            for parameter in paths["/api/mutations/catalog/"]["get"]["parameters"]
        }
        return (
            "/api/mutations/" in paths
            and "/api/mutations/catalog/" in paths
            and parameter_names == {"page", "page_size", "search", "model_label"}
        )

    def canonical_request(
        self, data: dict[str, Any], *, admin: bool = True
    ) -> HttpResponse:
        """Send a model-label mutation through normal endpoint authorization."""
        request = APIRequestFactory().post("/api/mutations/", data, format="json")
        force_authenticate(request, user=self.admin_user if admin else self.normal_user)
        response = AssistantMutationView.as_view()(request)
        response.render()
        return response

    def test_mutate_with_shared_model_label(self) -> None:
        """Create, update, and delete directly with the identity used by object artifacts."""
        identity = {"model_label": Initiative._meta.label.lower()}
        response = self.canonical_request(
            {
                **identity,
                "operation": "create",
                "data": {"name": "Canonical", "description": "Initial description"},
            }
        )
        self.assertEqual(response.status_code, 201)
        self.assertEqual(response.data["model_label"], Initiative._meta.label)
        object_id = response.data["object"]["id"]
        response = self.canonical_request(
            {
                **identity,
                "operation": "update",
                "object_id": object_id,
                "data": {"name": "Updated by label"},
            }
        )
        self.assertEqual(response.status_code, 200)
        self.assertEqual(Initiative.objects.get(pk=object_id).name, "Updated by label")
        response = self.canonical_request(
            {**identity, "operation": "delete", "object_id": object_id}
        )
        self.assertEqual(response.status_code, 200)
        self.assertFalse(Initiative.objects.filter(pk=object_id).exists())

    def test_model_label_preserves_write_denial(self) -> None:
        """A shared model label grants no write access to a normal user."""
        response = self.canonical_request(
            {
                "model_label": Initiative._meta.label,
                "operation": "create",
                "data": {"name": "Denied by label", "description": "Initial description"},
            },
            admin=False,
        )
        self.assertEqual(response.status_code, 403)
        self.assertFalse(Initiative.objects.filter(name="Denied by label").exists())

    def test_legacy_resource_with_model_label_is_rejected(self) -> None:
        """Reject obsolete keys even when a valid model label is also supplied."""
        response = self.canonical_request(
            {
                "model_label": Initiative._meta.label,
                "resource": "users",
                "operation": "create",
                "data": {},
            }
        )
        self.assertEqual(response.status_code, 400)
        self.assertIn("resource", response.data)


class TestAssistantMutationMcpView(BloomerpMcpViewTestCase):
    """Verify mutation payloads across the actual MCP transport and generated API."""

    view_name = "api_assistant_mutations"

    def get_test_scenarios(self) -> list[McpRequestScenario]:
        """Persist object payloads and reject JSON strings before dispatching writes."""
        return [
            McpRequestScenario(
                name="Creates an initiative with an object payload over MCP",
                user=self.admin_user,
                arguments={
                    "model_label": Initiative._meta.label,
                    "operation": "create",
                    "data": {
                        "name": "MCP initiative",
                        "description": "Initial description",
                    },
                },
                expected=ExpectedResult(
                    response_validators=[self.mcp_is_error(False), self.initiative_created],
                ),
            ),
            McpRequestScenario(
                name="Updates an initiative with an object payload over MCP",
                user=self.admin_user,
                prepare=self.prepare_update,
                expected=ExpectedResult(
                    response_validators=[self.mcp_is_error(False), self.initiative_updated],
                ),
            ),
            McpRequestScenario(
                name="Rejects a JSON-encoded update payload over MCP",
                user=self.admin_user,
                prepare=self.prepare_string_update,
                expected=ExpectedResult(
                    response_validators=[self.mcp_is_error(), self.initiative_unchanged],
                ),
            ),
        ]

    def prepare_update(self, scenario: McpRequestScenario) -> None:
        """Create the target initiative and supply native object arguments."""
        self.initiative = Initiative.objects.create(
            name="Before", description="Initial description"
        )
        scenario.arguments = {
            "model_label": Initiative._meta.label,
            "operation": "update",
            "object_id": str(self.initiative.pk),
            "data": {"name": "Updated over MCP"},
        }

    def prepare_string_update(self, scenario: McpRequestScenario) -> None:
        """Reproduce the JSON string payload sent in the failed Heertech conversation."""
        self.prepare_update(scenario)
        scenario.arguments["data"] = '{"name": "Updated over MCP"}'

    def initiative_created(self, response: HttpResponse) -> bool:
        """Confirm the tool returned an object that was saved through the generated API."""
        payload = response.json()["result"]["structuredContent"]
        return Initiative.objects.filter(
            pk=payload["object"]["id"],
            name="MCP initiative",
            description="Initial description",
        ).exists()

    def initiative_updated(self, response: HttpResponse) -> bool:
        """Confirm a partial update persisted and returned the requested initiative name."""
        self.initiative.refresh_from_db()
        return (
            self.initiative.name == "Updated over MCP"
            and response.json()["result"]["structuredContent"]["object"]["name"]
            == self.initiative.name
        )

    def initiative_unchanged(self, response: HttpResponse) -> bool:
        """Confirm schema validation rejected the string without changing the target."""
        self.initiative.refresh_from_db()
        error_text = response.json()["result"]["content"][0]["text"]
        return self.initiative.name == "Before" and "object" in error_text


class AssistantModelIdentityTests(SimpleTestCase):
    """Keep model labels unambiguous when different apps share a plural name."""

    def test_labels_disambiguate_legacy_resource_collisions(self) -> None:
        """Resolve exact app labels while rejecting an ambiguous legacy resource."""
        first = Mock()
        first._meta.label_lower = "sales.customer"
        first._meta.verbose_name_plural = "Customers"
        second = Mock()
        second._meta.label_lower = "crm.customer"
        second._meta.verbose_name_plural = "Customers"
        with patch(
            "bloomerp.views.api.mutations.get_auto_api_models",
            return_value=[first, second],
        ):
            self.assertIs(resolve_assistant_model("sales.Customer"), first)
            self.assertIs(resolve_assistant_model("crm.Customer"), second)
            self.assertIsNone(resolve_assistant_model("customers"))
            self.assertIsNone(resolve_assistant_model("private.Customer"))

    def test_legacy_resource_is_rejected(self) -> None:
        """A plural resource key cannot select a model under the strict contract."""
        from bloomerp.views.api.mutations import AssistantMutationRequestSerializer

        serializer = AssistantMutationRequestSerializer(
            data={"resource": "initiatives", "operation": "create", "data": {}}
        )
        self.assertFalse(serializer.is_valid())
        self.assertIn("resource", serializer.errors)

    def test_catalog_and_retrieve_reject_legacy_resource_keys(self) -> None:
        """Reject old resource filters rather than returning an unfiltered catalog."""
        from bloomerp.views.api.mutations import (
            AssistantMutationCatalogQuerySerializer,
            AssistantObjectRetrieveRequestSerializer,
        )

        for serializer_class in (
            AssistantMutationCatalogQuerySerializer,
            AssistantObjectRetrieveRequestSerializer,
        ):
            with self.subTest(serializer=serializer_class.__name__):
                serializer = serializer_class(
                    data={
                        "model_label": "bloomerp.Initiative",
                        "resource": "initiatives",
                        "object_id": "42",
                    }
                )
                self.assertFalse(serializer.is_valid())
                self.assertIn("resource", serializer.errors)
